export function scalarOffsetToCodeUnit(text: string, offset: number): number {
  if (offset <= 0) return 0;
  let scalars = 0;
  let units = 0;
  for (const character of text) {
    if (scalars >= offset) break;
    units += character.length;
    scalars += 1;
  }
  return units;
}
